/* ---- from sql/create_shop_tables.sql ---- */
-- ============================================
-- 简易电商系统 (shop 模块) 建表脚本 - Oracle
-- 包含: 分类 / 商品 / 购物车 / 订单主表 / 订单明细
-- ============================================

-- 商品分类表
CREATE TABLE SHOP_CATEGORY (
    ID           VARCHAR2(32)  PRIMARY KEY,
    NAME         VARCHAR2(100) NOT NULL,
    SORT_NO      NUMBER        DEFAULT 0,
    CREATE_TIME  TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL
);
COMMENT ON TABLE  SHOP_CATEGORY IS '商品分类表';
COMMENT ON COLUMN SHOP_CATEGORY.ID IS '主键ID(UUID)';
COMMENT ON COLUMN SHOP_CATEGORY.NAME IS '分类名称';
COMMENT ON COLUMN SHOP_CATEGORY.SORT_NO IS '排序号(升序)';

-- 商品表
CREATE TABLE SHOP_PRODUCT (
    ID           VARCHAR2(32)   PRIMARY KEY,
    NAME         VARCHAR2(200)  NOT NULL,
    CATEGORY_ID  VARCHAR2(32),
    PRICE        NUMBER(12,2)   DEFAULT 0 NOT NULL,
    STOCK        NUMBER         DEFAULT 0 NOT NULL,
    DESCRIPTION  VARCHAR2(2000),
    IMAGE_URL    VARCHAR2(500),
    STATUS       NUMBER(1)      DEFAULT 1 NOT NULL,
    CREATE_TIME  TIMESTAMP      DEFAULT SYSTIMESTAMP NOT NULL,
    UPDATE_TIME  TIMESTAMP      DEFAULT SYSTIMESTAMP NOT NULL
);
CREATE INDEX IDX_SHOP_PRODUCT_CATEGORY ON SHOP_PRODUCT(CATEGORY_ID);
CREATE INDEX IDX_SHOP_PRODUCT_NAME     ON SHOP_PRODUCT(NAME);
COMMENT ON TABLE  SHOP_CATEGORY IS '商品分类表';
COMMENT ON TABLE  SHOP_PRODUCT IS '商品表';
COMMENT ON COLUMN SHOP_PRODUCT.PRICE IS '销售单价(元)';
COMMENT ON COLUMN SHOP_PRODUCT.STOCK IS '库存数量';
COMMENT ON COLUMN SHOP_PRODUCT.STATUS IS '状态: 1-上架, 0-下架';

-- 购物车表
CREATE TABLE SHOP_CART (
    ID           VARCHAR2(32)  PRIMARY KEY,
    USER_ID      VARCHAR2(100) NOT NULL,
    PRODUCT_ID   VARCHAR2(32)  NOT NULL,
    QUANTITY     NUMBER        DEFAULT 1 NOT NULL,
    CREATE_TIME  TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,
    UPDATE_TIME  TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL
);
CREATE UNIQUE INDEX UK_SHOP_CART_USER_PRODUCT ON SHOP_CART(USER_ID, PRODUCT_ID);
COMMENT ON TABLE  SHOP_CART IS '购物车表';
COMMENT ON COLUMN SHOP_CART.USER_ID IS '用户(工号)ID';

-- 订单主表
CREATE TABLE SHOP_ORDER (
    ID               VARCHAR2(32)  PRIMARY KEY,
    ORDER_NO         VARCHAR2(32)  NOT NULL,
    USER_ID          VARCHAR2(100) NOT NULL,
    TOTAL_AMOUNT     NUMBER(12,2)  DEFAULT 0 NOT NULL,
    STATUS           VARCHAR2(20)  DEFAULT 'PENDING' NOT NULL,
    RECEIVER_NAME    VARCHAR2(100),
    RECEIVER_PHONE   VARCHAR2(50),
    RECEIVER_ADDRESS VARCHAR2(500),
    REMARK           VARCHAR2(500),
    PAY_TIME         TIMESTAMP,
    CREATE_TIME      TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,
    UPDATE_TIME      TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL
);
CREATE UNIQUE INDEX UK_SHOP_ORDER_NO ON SHOP_ORDER(ORDER_NO);
CREATE INDEX IDX_SHOP_ORDER_USER ON SHOP_ORDER(USER_ID);
CREATE INDEX IDX_SHOP_ORDER_STATUS ON SHOP_ORDER(STATUS);
COMMENT ON TABLE  SHOP_ORDER IS '电商订单主表';
COMMENT ON COLUMN SHOP_ORDER.STATUS IS '订单状态: PENDING-待支付, PAID-已支付, CANCELLED-已取消';

-- 订单明细表
CREATE TABLE SHOP_ORDER_ITEM (
    ID            VARCHAR2(32)  PRIMARY KEY,
    ORDER_ID      VARCHAR2(32)  NOT NULL,
    PRODUCT_ID    VARCHAR2(32)  NOT NULL,
    PRODUCT_NAME  VARCHAR2(200),
    PRICE         NUMBER(12,2)  DEFAULT 0 NOT NULL,
    QUANTITY      NUMBER        DEFAULT 1 NOT NULL,
    SUBTOTAL      NUMBER(12,2)  DEFAULT 0 NOT NULL
);
CREATE INDEX IDX_SHOP_ORDER_ITEM_ORDER ON SHOP_ORDER_ITEM(ORDER_ID);
COMMENT ON TABLE  SHOP_ORDER_ITEM IS '电商订单明细表';

/* ---- from sql/create_shop_user.sql ---- */
-- ============================================
-- 电商独立客户账号表 SHOP_USER - Oracle
-- 商城登录已完全独立于 MES 员工体系, 不再查询 USERPROFILE
--
-- 口径说明（重要）:
--   JWT subject 以及 SHOP_ORDER / SHOP_CART / SHOP_ADDRESS 的 USER_ID 存的都是 USERNAME,
--   不是这里的 ID。存量数据就是这个口径, 不要改成 ID, 否则历史订单和购物车会全部查不到。
--
-- 本文件可直接整体执行(建表 + 索引 + 注释)。
-- 下面两段"账号数据"默认用 -- 注释掉, 按场景二选一手工放开后再执行。
-- ============================================

CREATE TABLE SHOP_USER (
    ID           VARCHAR2(32)   PRIMARY KEY,
    USERNAME     VARCHAR2(100)  NOT NULL,
    PASSWORD     VARCHAR2(200)  NOT NULL,
    NICKNAME     VARCHAR2(100),
    PHONE        VARCHAR2(50),
    EMAIL        VARCHAR2(100),
    ROLE         VARCHAR2(100),
    STATUS       NUMBER(1)      DEFAULT 1 NOT NULL,
    CREATE_TIME  TIMESTAMP      DEFAULT SYSTIMESTAMP NOT NULL,
    UPDATE_TIME  TIMESTAMP      DEFAULT SYSTIMESTAMP NOT NULL
);
CREATE UNIQUE INDEX UK_SHOP_USER_USERNAME ON SHOP_USER(USERNAME);

COMMENT ON TABLE  SHOP_USER IS '电商客户账号表';
COMMENT ON COLUMN SHOP_USER.ID IS '主键ID(UUID)。仅作主键, 登录态和业务表 USER_ID 都用 USERNAME';
COMMENT ON COLUMN SHOP_USER.USERNAME IS '登录账号(唯一), 同时作为 JWT subject 与订单/购物车/地址的 USER_ID';
COMMENT ON COLUMN SHOP_USER.PASSWORD IS '密码摘要: md5(md5(明文) + 明文前5位), 32位小写hex';
COMMENT ON COLUMN SHOP_USER.NICKNAME IS '昵称, 登录接口里以 fullname 返回给前端做显示名';
COMMENT ON COLUMN SHOP_USER.ROLE IS '角色, 写入 JWT role claim, 命中 shop.admin-positions 才能进后台管理';
COMMENT ON COLUMN SHOP_USER.STATUS IS '状态: 1-正常, 0-禁用';

/* ---- from sql/create_shop_address_table.sql ---- */
-- ============================================
-- 电商收货地址簿 - Oracle
-- 用途: 下单时从地址簿选择收货人信息, 不再每次手填
-- 说明: USER_ID 与 SHOP_ORDER.USER_ID 同一套口径, 存的是登录账号(JWT subject), 不是 USERPROFILE.USERID
-- ============================================

CREATE TABLE SHOP_ADDRESS (
    ID               VARCHAR2(32)  PRIMARY KEY,
    USER_ID          VARCHAR2(100) NOT NULL,
    RECEIVER_NAME    VARCHAR2(100) NOT NULL,
    RECEIVER_PHONE   VARCHAR2(50)  NOT NULL,
    RECEIVER_ADDRESS VARCHAR2(500) NOT NULL,
    IS_DEFAULT       NUMBER(1)     DEFAULT 0 NOT NULL,
    CREATE_TIME      TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,
    UPDATE_TIME      TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL
);

-- 一个用户的默认地址最多一条; 没有默认地址时下单取最早创建的那条
-- 这里必须用函数索引: 假设写成 (USER_ID, IS_DEFAULT) 的唯一索引,
-- 同一用户的多条非默认地址都是 (user, 0), 会互相冲突, 地址簿只能存一条。
-- CASE 非默认时返回 NULL, Oracle 唯一索引不校全 NULL 键, 所以可以共存。
CREATE UNIQUE INDEX UK_SHOP_ADDRESS_DEFAULT
    ON SHOP_ADDRESS (CASE WHEN IS_DEFAULT = 1 THEN USER_ID ELSE NULL END);
CREATE INDEX IDX_SHOP_ADDRESS_USER ON SHOP_ADDRESS(USER_ID);

COMMENT ON TABLE  SHOP_ADDRESS IS '电商收货地址簿';
COMMENT ON COLUMN SHOP_ADDRESS.USER_ID IS '所属用户(登录账号)';
COMMENT ON COLUMN SHOP_ADDRESS.IS_DEFAULT IS '是否默认收货地址: 1-是, 0-否';
COMMENT ON COLUMN SHOP_ADDRESS.RECEIVER_ADDRESS IS '收货地址(省市区+详细地址)';

/* ---- from sql/create_pda_payment_order.sql ---- */
-- ============================================
-- 支付宝支付订单表
-- ============================================
CREATE TABLE PDA_PAYMENT_ORDER (
    ID              VARCHAR2(64)    PRIMARY KEY,
    OUT_TRADE_NO    VARCHAR2(64)    NOT NULL,
    TRADE_NO        VARCHAR2(128),
    SUBJECT         VARCHAR2(256),
    TOTAL_AMOUNT    NUMBER(12,2)    NOT NULL,
    ORDER_STATUS    VARCHAR2(32)    DEFAULT 'WAIT_PAY' NOT NULL,
    BUYER_LOGON_ID  VARCHAR2(128),
    BUYER_ID        VARCHAR2(64),
    PAY_TIME        TIMESTAMP,
    NOTIFY_TIME     TIMESTAMP,
    CREATE_BY       VARCHAR2(64),
    CREATE_TIME     TIMESTAMP       DEFAULT SYSTIMESTAMP NOT NULL,
    UPDATE_BY       VARCHAR2(64),
    UPDATE_TIME     TIMESTAMP       DEFAULT SYSTIMESTAMP NOT NULL,
    REMARK          VARCHAR2(512)
);

-- 商户订单号唯一索引
CREATE UNIQUE INDEX IDX_PAYMENT_OUT_TRADE_NO ON PDA_PAYMENT_ORDER(OUT_TRADE_NO);

-- 交易号索引 (用于退款查询)
CREATE INDEX IDX_PAYMENT_TRADE_NO ON PDA_PAYMENT_ORDER(TRADE_NO);

-- 订单状态索引
CREATE INDEX IDX_PAYMENT_STATUS ON PDA_PAYMENT_ORDER(ORDER_STATUS);

-- 创建时间索引
CREATE INDEX IDX_PAYMENT_CREATE_TIME ON PDA_PAYMENT_ORDER(CREATE_TIME);

COMMENT ON TABLE PDA_PAYMENT_ORDER IS '支付宝支付订单表';
COMMENT ON COLUMN PDA_PAYMENT_ORDER.ID IS '主键ID';
COMMENT ON COLUMN PDA_PAYMENT_ORDER.OUT_TRADE_NO IS '商户订单号(业务系统生成,唯一)';
COMMENT ON COLUMN PDA_PAYMENT_ORDER.TRADE_NO IS '支付宝交易号';
COMMENT ON COLUMN PDA_PAYMENT_ORDER.SUBJECT IS '订单标题/描述';
COMMENT ON COLUMN PDA_PAYMENT_ORDER.TOTAL_AMOUNT IS '支付金额(单位:元)';
COMMENT ON COLUMN PDA_PAYMENT_ORDER.ORDER_STATUS IS '订单状态: WAIT_PAY-待支付, PAID-已支付, CLOSED-已关闭, REFUNDED-已退款';
COMMENT ON COLUMN PDA_PAYMENT_ORDER.BUYER_LOGON_ID IS '买家支付宝账号';
COMMENT ON COLUMN PDA_PAYMENT_ORDER.BUYER_ID IS '买家支付宝用户ID';
COMMENT ON COLUMN PDA_PAYMENT_ORDER.PAY_TIME IS '支付时间';
COMMENT ON COLUMN PDA_PAYMENT_ORDER.NOTIFY_TIME IS '通知时间';
COMMENT ON COLUMN PDA_PAYMENT_ORDER.CREATE_BY IS '创建人';
COMMENT ON COLUMN PDA_PAYMENT_ORDER.CREATE_TIME IS '创建时间';
COMMENT ON COLUMN PDA_PAYMENT_ORDER.UPDATE_BY IS '更新人';
COMMENT ON COLUMN PDA_PAYMENT_ORDER.UPDATE_TIME IS '更新时间';
COMMENT ON COLUMN PDA_PAYMENT_ORDER.REMARK IS '备注';


